const items = $input.all();

const THRESHOLDS = {
  intake: 3,
  briefing_done: 7,
  design_done: 7,
  analysis_done: 7,
  costs_done: 5,
  trades_done: 5,
  proposal_done: 5,
  approved: 10,
  planning_done: 14
};

const projects = items.map(item => {
  const p = item.json;
  const threshold = THRESHOLDS[p.current_phase] || 7;
  const daysStale = parseFloat(p.days_stale) || 0;
  const isStale = daysStale > threshold;
  return {
    ...p,
    days_stale: Math.floor(daysStale),
    threshold_days: threshold,
    is_stale: isStale,
    staleness_level: isStale ? (daysStale > threshold * 2 ? 'critical' : 'warning') : 'ok',
    pending_consultations: parseInt(p.pending_consultations) || 0
  };
});

const stale = projects.filter(p => p.is_stale);
const ok = projects.filter(p => !p.is_stale);

const buildRow = (p, highlight) => `<tr style="background:${highlight};">
  <td style="padding:8px;border:1px solid #ddd">${p.project_name}</td>
  <td style="padding:8px;border:1px solid #ddd">${p.client_name}</td>
  <td style="padding:8px;border:1px solid #ddd"><code>${p.current_phase}</code></td>
  <td style="padding:8px;border:1px solid #ddd;font-weight:bold">${p.days_stale}d</td>
  <td style="padding:8px;border:1px solid #ddd">${p.pending_consultations > 0 ? '⚠️ ' + p.pending_consultations + ' pendiente(s)' : '—'}</td>
</tr>`;

const staleRows = stale.map(p => buildRow(p, p.staleness_level === 'critical' ? '#ffe0e0' : '#fff8e1')).join('');
const okRows = ok.map(p => buildRow(p, '#ffffff')).join('');
const header = `<tr style="background:#f5f5f5"><th style="padding:8px;border:1px solid #ddd">Proyecto</th><th style="padding:8px;border:1px solid #ddd">Cliente</th><th style="padding:8px;border:1px solid #ddd">Fase</th><th style="padding:8px;border:1px solid #ddd">Días sin avanzar</th><th style="padding:8px;border:1px solid #ddd">Consultas</th></tr>`;

const now = new Date().toLocaleString('es-ES', {timeZone: 'Europe/Madrid'});

const body = `<html><body style="font-family:Arial,sans-serif;padding:20px">
<h2>Revisión de Proyectos Activos</h2>
<p>Generado: ${now} &nbsp;|&nbsp; Total activos: ${projects.length} &nbsp;|&nbsp; Requieren atención: ${stale.length}</p>

${stale.length > 0 ? `<h3 style="color:#e53935">⚠️ ${stale.length} proyecto(s) sin avanzar</h3>
<table style="border-collapse:collapse;width:100%">${header}${staleRows}</table><br>` : '<p style="color:#43a047">✅ Todos los proyectos están al día.</p>'}

${ok.length > 0 ? `<h3 style="color:#555">Proyectos al día (${ok.length})</h3>
<table style="border-collapse:collapse;width:100%">${header}${okRows}</table>` : ''}

<br><hr><small>Sistema multiagente &mdash; revisión automática cada 6 horas.</small>
</body></html>`;

const subject = stale.length > 0
  ? `[⚠️ ${stale.length} proyectos bloqueados] Revisión de proyectos ${new Date().toLocaleDateString('es-ES')}`
  : `[OK] Revisión de proyectos ${new Date().toLocaleDateString('es-ES')} — ${projects.length} activos`;

return [{
  json: {
    projects_count: projects.length,
    stale_count: stale.length,
    email_subject: subject,
    email_body: body,
    has_projects: projects.length > 0
  }
}];
